class VideoPlayer(private val url: String) {
    var isInitialized = false
    var isPlaying = false
    var isPaused = false
    var isBuffering = false
    var hasEnded = false
    var hasError = false
    var errorMessage: String? = null
    var isMuted = false
    private var engine: Engine? = null

    fun init() { engine = Engine(url); isInitialized = true }
    fun play() {
        if (!isInitialized) throw IllegalStateException("call init first")
        if (hasError) return
        engine!!.start(); isPlaying = true; isPaused = false; hasEnded = false
    }
    fun pause() { if (!isInitialized) return; engine!!.pause(); isPaused = true; isPlaying = false }
    fun seek(positionMs: Long, resume: Boolean) {
        if (!isInitialized) return
        engine!!.seekTo(positionMs)
        if (resume) play() else pause()
    }
    fun onEngineError(msg: String) { hasError = true; errorMessage = msg; isPlaying = false; isBuffering = false }
    fun onBuffering(buffering: Boolean) { isBuffering = buffering }
    fun onEnded() { hasEnded = true; isPlaying = false }
}
