we're adding Razorpay as a third payment provider to our node checkout service (typescript 5.6). stripe and paypal are handled with if/else in a few places, relevant bits below. can you add razorpay? their sdk: `razorpay.orders.create({ amount, currency })` returns `{ id }`, refunds are `razorpay.payments.refund(paymentId, { amount })`, and their webhook signature header is `x-razorpay-signature`. fee is 2% flat.

```ts
import { stripe, paypal } from "./clients";

export type Provider = "stripe" | "paypal";

export async function charge(provider: Provider, amountMinor: number, currency: string): Promise<string> {
  if (provider === "stripe") {
    const intent = await stripe.paymentIntents.create({ amount: amountMinor, currency });
    return intent.id;
  } else if (provider === "paypal") {
    const order = await paypal.orders.create({ value: (amountMinor / 100).toFixed(2), currency });
    return order.id;
  }
  throw new Error("unknown provider");
}

export async function refund(provider: Provider, paymentId: string, amountMinor: number): Promise<void> {
  if (provider === "stripe") {
    await stripe.refunds.create({ payment_intent: paymentId, amount: amountMinor });
  } else {
    await paypal.captures.refund(paymentId, { value: (amountMinor / 100).toFixed(2) });
  }
}

export function signatureHeader(provider: Provider): string {
  return provider === "stripe" ? "stripe-signature" : "paypal-transmission-sig";
}

export function feeMinor(provider: Provider, amountMinor: number): number {
  if (provider === "stripe") return Math.round(amountMinor * 0.029) + 30;
  return Math.round(amountMinor * 0.0349) + 49;
}
```

