```kotlin
interface AnalyticsTracker {
    fun track(event: String, props: Map<String, Any>)
}

class FirebaseAnalyticsTracker(private val fa: FirebaseAnalytics) : AnalyticsTracker {
    override fun track(event: String, props: Map<String, Any>) {
        fa.logEvent(event, bundleOf(*props.map { it.key to it.value }.toTypedArray()))
    }
}

abstract class AnalyticsTrackerFactory {
    abstract fun create(): AnalyticsTracker
}

class DefaultAnalyticsTrackerFactory(private val fa: FirebaseAnalytics) : AnalyticsTrackerFactory() {
    override fun create(): AnalyticsTracker = FirebaseAnalyticsTracker(fa)
}

object AnalyticsManager {
    private lateinit var tracker: AnalyticsTracker
    fun init(factory: AnalyticsTrackerFactory) { tracker = factory.create() }
    fun trackPurchase(orderId: String, amount: Double) =
        tracker.track("purchase", mapOf("order_id" to orderId, "amount" to amount))
    fun trackScreen(name: String) = tracker.track("screen_view", mapOf("screen" to name))
}
